func FuzzDecodeDummyToggleSymbolConfig(f *testing.F) {
	{
		seed := fullyPopulatedDummyToggleSymbolConfig
		w := orc.NewWriter(0)
		if err := seed.EncodeOrc(w); err != nil {
			f.Fatal(err)
		}
		f.Add(w.Bytes())
	}
	{
		seed := v13.DummyToggleSymbolConfig{
			Label: v13.LabelConfig{
				Label:         "",
				Level:         text.Level(""),
				Orientation:   spatial.Location(""),
				Direction:     spatial.Direction(""),
				MaxInlineSize: 0,
				Align:         v13.FlexAlignment(""),
			},
			Orientation: spatial.OuterLocation(""),
			Scale:       0,
			Enabled:     false,
			Clickable:   false,
			StrokeColor: nil,
		}
		w := orc.NewWriter(0)
		if err := seed.EncodeOrc(w); err != nil {
			f.Fatal(err)
		}
		f.Add(w.Bytes())
	}
	f.Fuzz(func(t *testing.T, data []byte) {
		var decoded v13.DummyToggleSymbolConfig
		r := orc.NewReader(nil)
		r.ResetBytes(data)
		if err := decoded.DecodeOrc(r); err != nil {
			return
		}
		w1 := orc.NewWriter(len(data))
		if err := decoded.EncodeOrc(w1); err != nil {
			t.Fatalf("encode after successful decode failed: %v", err)
		}
		var redecoded v13.DummyToggleSymbolConfig
		r.ResetBytes(w1.Bytes())
		if err := redecoded.DecodeOrc(r); err != nil {
			t.Fatalf("re-decode failed: %v", err)
		}
		if !testutil.DeepEqual(decoded, redecoded) {
			t.Fatal("round-trip mismatch: decoded value changed after an encode/decode cycle")
		}
	})
}

